      `,confirmButtonColor:"#991b1b",confirmButtonText:"DONE",customClass:{popup:"rounded-[2rem]"}})},B=async D=>{const{value:q}=await ki.fire({title:'<b style="color: #991b1b;">PASSWORD OVERRIDE</b>',html:`
